//
// METHOD / CAVEATS
// - AZGFD reports draw-hunt results per HUNT NUMBER; many hunts span several units.
//   Rows are aggregated (harvest + hunters summed) per the agency's unit or unit-GROUP
//   label for each hunt, e.g. '1-2B-2C' = hunts open in Units 1, 2B and 2C together.
//   Named hunt areas, Hopi-land hunts and "(except Camp Navajo)" notes are folded into
//   their parent unit/group. Camp Navajo and Fort Huachuca military hunts keep their own ids.
//   The reports' "multi-unit breakdown" pages were NOT used (they do not reconcile with
//   the hunt totals, e.g. Unit 1 always shows 0 hunters).
// - successRate = totalHarvest / totalHunters * 100 (1 decimal), recomputed from the
//   reported totals. totalHunters 0 = not published (bear and lion reports give harvest only).
// - Elk: bulls = bull + spike; cows = cow (2024 report: "antlerless", calves not split out).
// - Deer: the questionnaire splits harvest into mule deer / whitetail but not hunters.
//   Hunters of a hunt are counted for a species only if that species was legal on the hunt
//   per the same-year regulations (mule-deer-only, whitetail-only or any-deer hunts); OTC
//   archery hunters (any antlered deer) count for both. Hopi-land deer hunts (legal animal
//   not in the regs) are excluded. Military draw hunts (report hunt nos. 1901-1906, listed
//   as '----' in the regs: Camp Navajo 1901 any antlered deer; Fort Huachuca 1902-1903
//   antlered whitetail, 1904-1906 any antlered deer) are classified from those reg entries.
//   bulls = bucks, cows = antlerless. Unit/species pairs with zero harvest in every year and
//   no species-specific hunt are omitted (e.g. whitetail on the Arizona Strip).
// - Sheep: hunt-level harvest/hunters; "-" (no harvest) = 0. Auction/raffle special tags
//   (statewide, no unit) are not included.
// - Bear: hunter harvest only (excludes "other" and depredation); totalHunters 0 (tag sales
//   are statewide only).
// - Lion: AZGFD reports by lion management zone (A–P); ids are 'zone-<letter>'.
// Rows: elk 120, mule deer 175, whitetail 130, pronghorn 104,
//       bighorn sheep 140, black bear 100, mountain lion 48.
// ============================================================

export interface RealGMUData {
  gmu: string;
  species: string;
  year: number;
  totalHarvest: number;
  totalHunters: number;
  successRate: number; // percentage 0-100 (0 = hunters not published)
  bulls?: number; // or bucks
  cows?: number; // or does / antlerless
  calves?: number;
  recDays?: number; // hunter days
}

